const state={page:'home',selected:0,region:'all',metric:'level',range:'6h',paused:false,motionPaused:false,storm:false,chart:null,category:'全部内容',search:'',image:null,sample:false,detecting:false,results:[],detectionTimer:null,uploadToken:0,alerts:[{station:1,time:new Date(),title:'江宁闸站水位超过演示阈值',kind:'warn'}],tick:0};
const histories=stations.map(s=>Array.from({length:25},(_,i)=>({level:+(s.base+Math.sin(i/3)*.16-(24-i)*.006).toFixed(2),flow:Math.round(s.flow+Math.sin(i/3)*90),ph:+(s.ph+Math.sin(i/4)*.08).toFixed(2)})));
const metricMeta={level:{name:'水位',unit:'m',color:'#4adef1',key:'水位'},flow:{name:'流量',unit:'m³/s',color:'#4bdab0',key:'流量'},ph:{name:'水质 pH',unit:'pH',color:'#b398ff',key:'pH'}};
