function mapSvg(){return `<svg class="base-map" viewBox="0 0 780 400" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="mapwater" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#105a78"/><stop offset="1" stop-color="#14728c"/></linearGradient><pattern id="trees" width="30" height="25" patternUnits="userSpaceOnUse"><circle cx="15" cy="10" r="1" fill="#184358"/></pattern></defs><path fill="#091b2a" d="M0 0h780v400H0z"/><path d="M0 0h275l-40 64-86 40-48 86L0 170ZM780 0H490l65 95 94 32 80 80 51-24ZM780 400H505l39-55 112-42 124 25ZM0 400V284l98-31 102 26 47 121Z" fill="#102b36"/><path fill="url(#trees)" d="M0 0h780v400H0z"/><g fill="none" stroke="#285044" stroke-width=".8">${Array.from({length:6},(_,i)=>`<path d="M${-30+i*17} 0C${140+i*14} 90 ${150+i*19} 80 ${90+i*20} 200S${-70+i*15} 300 ${50+i*16} 400"/><path d="M${550+i*25} 0c-130 120 70 90 20 220s10 130 90 180"/>`).join('')}</g><g stroke="#1d3949" stroke-width="6" fill="none"><path d="m0 117 155 44 202-20 162 74 261 9M78 0l100 151 29 101 87 148M640 0 534 110l-57 170-30 120M0 331l204-79 242 28 334-82"/></g><g stroke="#295269" stroke-width="1" fill="none"><path d="m0 117 155 44 202-20 162 74 261 9M78 0l100 151 29 101 87 148M640 0 534 110l-57 170-30 120M0 331l204-79 242 28 334-82"/></g><path d="M185-30C154 39 304 39 323 100S206 187 264 237s193 34 176 105 25 82 25 82" stroke="#16475d" stroke-width="66" fill="none"/><path d="M185-30C154 39 304 39 323 100S206 187 264 237s193 34 176 105 25 82 25 82" stroke="url(#mapwater)" stroke-width="42" fill="none"/><path d="M330 108C433 77 460 119 542 72S682 44 733-25M269 230C378 258 388 291 552 329S666 338 795 370" stroke="#1b6278" stroke-width="17" fill="none"/><path d="M660 200c-22-23-57-11-54 7s45 23 40 47 26 46 47 23 12-47-7-50-13-15-26-27" fill="#16435b"/><path d="M85 304c-28-18-55 14-35 42s58 34 78 8-17-39-43-50" fill="#16435b"/><path class="flow-line" d="M185-30C154 39 304 39 323 100S206 187 264 237s193 34 176 105 25 82 25 82" fill="none" stroke="#65e4ec" stroke-width="1.5"/><g fill="#668c9f" font-size="10" font-family="sans-serif" letter-spacing="3"><text x="85" y="84">浦口区</text><text x="470" y="57">栖霞区</text><text x="515" y="188">城市观测区</text><text x="145" y="258">江宁区</text><text x="553" y="373">湖库生态区</text></g><g fill="#4c9db7" font-size="9" letter-spacing="5"><text x="317" y="164" transform="rotate(-45 317 164)">长江</text><text x="470" y="322" transform="rotate(14 470 322)">秦淮河</text><text x="74" y="331" font-size="7" letter-spacing="1">湖区</text></g><g stroke="#2b465b" stroke-dasharray="4 5" fill="none"><path d="M0 222C200 222 203 64 409 190s229 63 371 35"/><path d="M396 0c-22 127 159 203 162 400"/></g></svg>`}

function header(title,desc,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function statCards(){const list=visibleStations(),s=stations[state.selected],warn=list.filter(isWarn).length;return `<div class="stats-grid">
${stat('实时水位',fmt(s.level),'m','drop','',`${s.name} · <span class="${isWarn(s)?'negative':'positive'}">${isWarn(s)?'超过阈值':'阈值内'}</span>`,'#4695ee')}
${stat('瞬时流量',fmt(s.flow,0),'m³/s','flow','teal','<span class="positive">↗</span> 持续采集模拟数据','#27b6a3')}
${stat('水质 pH',fmt(s.ph,1),'pH','quality','purple','酸碱度模拟值 · 查看指标趋势','#9e8bda')}
${stat('在线监测点',String(list.length).padStart(2,'0'),`/ ${list.length} 个`,'pin','orange',`<span class="${warn?'negative':'positive'}">${warn?'● '+warn+' 个水位预警':'● 全部水位正常'}</span>`,'#e9ae5c')}
</div>`}
function stat(title,value,unit,type,color,bottom,stroke){return `<div class="stat-card"><div class="stat-top"><span>${title}</span><span class="stat-icon ${color}">${icon(type)}</span></div><div class="stat-value"><strong data-stat="${type}">${value}</strong><small>${unit}</small></div><div class="stat-bottom" data-bottom="${type}">${bottom}</div><svg class="sparkline" viewBox="0 0 70 30" fill="none" aria-hidden="true"><path d="m1 24 6-3 5 2 7-8 6 3 7-6 6 2 7-7 5 4 6-9 5 3 8-4" stroke="${stroke}" stroke-width="1.5"/><path d="m1 24 6-3 5 2 7-8 6 3 7-6 6 2 7-7 5 4 6-9 5 3 8-4V30H1Z" fill="${stroke}" fill-opacity=".06"/></svg></div>`}
function regionSelect(){return `<select id="region-select" aria-label="选择监测区域">${Object.entries(groupNames).map(([key,name])=>`<option value="${key}" ${key===state.region?'selected':''}>${name}</option>`).join('')}</select>`}
function mapPanel(){return `<section class="panel"><div class="panel-heading"><div><div class="panel-title"><h2>流域感知地图</h2><span class="badge blue">${visibleStations().length} 个点位</span></div><p class="panel-subtitle">长江下游 · 南京片区示意</p></div><div class="panel-tools">${regionSelect()}<button class="icon-button" id="map-expand" aria-label="全屏查看地图">${icon('expand')}</button></div></div><div class="map" id="river-map">${mapSvg()}<div class="map-grid"></div><div class="map-compass">N<i class="compass-arrow"></i></div><div id="map-pins">${mapPins()}</div><span class="map-caption">SCHEMATIC MAP · 非地理测绘数据</span><div class="map-legend"><span><i class="legend-dot"></i> 正常监测</span><span><i class="legend-dot red"></i> 水位预警</span></div></div><div class="map-detail" id="map-detail">${mapDetail()}</div>${state.page==='monitor'?`<div class="water-widget"><div class="water-orb"><span>LIVE</span></div><div><h3>每一次变化，都被看见</h3><p>每 3 秒更新 · 阈值仅用于交互演示</p></div><button class="btn ${state.storm?'danger':''}" id="simulate-storm">${icon('warning')}${state.storm?'恢复常态':'模拟水位上涨'}</button></div>`:''}</section>`}
function mapPins(){return visibleStations().map(s=>{const i=stationIndex(s);return `<button class="station-pin ${isWarn(s)?'warn':''} ${i===state.selected?'selected':''}" data-station="${i}" style="left:${s.x}%;top:${s.y}%" aria-label="${s.name}，水位 ${fmt(s.level)} 米，${isWarn(s)?'预警':'正常'}" aria-pressed="${i===state.selected}"><span class="pin-circle"></span><span class="pin-label" ${s.x>76?'style="left:auto;right:20px"':''}>${s.name}</span><span class="pin-hover">${fmt(s.level)} m · ${fmt(s.flow,0)} m³/s · pH ${fmt(s.ph,1)}</span></button>`}).join('')}
function mapDetail(){const s=stations[state.selected];return `<span class="map-detail-name"><i class="legend-dot ${isWarn(s)?'red':''}"></i>${s.name}<span class="badge ${isWarn(s)?'red':'green'}">${isWarn(s)?'水位预警':'正常'}</span></span><span class="map-detail-values"><span>水位<b>${fmt(s.level)} m</b></span><span>流量<b>${fmt(s.flow,0)} m³/s</b></span><span>pH<b>${fmt(s.ph,1)}</b></span></span>`}
function chartPanel(){return `<section class="panel"><div class="panel-heading"><div><div class="panel-title"><h2>实时趋势分析</h2></div><p class="panel-subtitle" id="chart-station">${stations[state.selected].name} · 模拟历史与实时数据</p></div><div class="segmented" id="range-tabs" aria-label="趋势时间范围">${['1h','6h','24h'].map(r=>`<button data-range="${r}" class="${r===state.range?'active':''}" aria-pressed="${r===state.range}">${r.toUpperCase()}</button>`).join('')}</div></div><div style="display:flex;justify-content:space-between;align-items:center;margin:0 21px 12px"><div class="segmented" id="metric-tabs" aria-label="选择监测指标">${Object.entries(metricMeta).map(([key,m])=>`<button data-metric="${key}" class="${key===state.metric?'active':''}" aria-pressed="${key===state.metric}">${m.name}</button>`).join('')}</div><span class="live-caption"><i class="status-dot"></i><span class="refresh-label">${state.paused?'已暂停':'动态采集'}</span></span></div><div class="chart-summary" id="chart-summary">${chartSummary()}</div><div class="chart-area"><canvas id="trend-chart" role="img" aria-label="当前监测点的模拟数据趋势折线图"></canvas></div><div class="chart-note"><span><i></i><span id="chart-legend">${metricMeta[state.metric].name} (${metricMeta[state.metric].unit})</span></span><span>每 3 秒刷新 · 前端模拟</span></div></section>`}
function chartSummary(){const s=stations[state.selected],m=metricMeta[state.metric];return `<strong>${fmt(s[state.metric],state.metric==='flow'?0:2)}</strong><span>${m.unit}</span><span class="badge ${state.metric==='level'&&isWarn(s)?'red':'green'}">${state.metric==='level'?(isWarn(s)?'超过演示阈值':'阈值内运行'):'模拟采集值'}</span>`}
function stationTable(full=false){return `<section class="panel"><div class="panel-heading"><div class="panel-title"><h2>监测点位状态</h2><span class="badge">${visibleStations().length} 站</span></div>${full?'<span class="live-caption">点选站点联动地图与曲线</span>':'<a href="#/monitor" class="btn text">全部点位 →</a>'}</div><div class="table-scroll"><table class="station-table"><thead><tr><th>监测站点</th><th>实时水位</th><th>${full?'流量 / pH':'演示阈值'}</th><th>运行状态</th><th>操作</th></tr></thead><tbody id="station-table-body">${tableRows(full)}</tbody></table></div></section>`}
function tableRows(full=false){return (full?visibleStations():visibleStations().slice(0,4)).map(s=>`<tr><td>${s.name}</td><td>${fmt(s.level)} m</td><td>${full?fmt(s.flow,0)+' / '+fmt(s.ph,1):fmt(s.limit)+' m'}</td><td><span class="badge ${isWarn(s)?'red':'green'}">${isWarn(s)?'水位预警':'正常'}</span></td><td><button class="table-link" data-view-station="${stationIndex(s)}">查看</button></td></tr>`).join('')}
function alertsPanel(){return `<section class="panel"><div class="panel-heading"><div class="panel-title"><h2>预警与动态</h2><span class="badge orange">模拟事件</span></div><button class="btn text" id="all-alerts">查看记录 →</button></div><div class="alert-list" id="alert-list">${alertsHTML()}</div><a class="quick-link" href="#/ai">${icon('scan')}<span><strong>探索 AI 水下识别</strong><small>从一张图片，感知水下世界</small></span><span>↗</span></a></section>`}
function alertsHTML(){const a=state.alerts[0];return `${a?`<div class="alert-item"><span class="alert-mark ${a.kind==='info'?'info':''}">${icon(a.kind==='info'?'check':'warning')}</span><div class="alert-content"><h3>${a.title}</h3><p>${a.kind==='info'?'演示场景已恢复，持续观察模拟数据。':'超过前端预设阈值，请查看站点详情。'}</p><time>${timeString(a.time)} · 前端模拟</time></div><button data-alert="${a.station}">详情</button></div>`:''}<div class="alert-item"><span class="alert-mark info">${icon('refresh')}</span><div class="alert-content"><h3>监测数据流已接入</h3><p>8 个模拟站点持续刷新，探索流域变化。</p><time>系统动态 · 演示模式</time></div></div>`}

function renderHome(){return `<section class="cinematic-hero" aria-labelledby="hero-title"><div class="hero-atmosphere" aria-hidden="true"><div class="orbital-halo"></div><div class="horizon-line"></div></div><div class="hero-scene" aria-hidden="true"><div class="terrain-fallback">${riverArt()}</div><canvas id="digital-river"></canvas></div><div class="scene-coordinate scene-coordinate-top"><span>LOWER YANGTZE / DIGITAL WATERSHED</span><b>数字流域 · 概念可视化</b></div><div class="cinematic-copy"><div class="hero-kicker"><span class="signal-square"></span> HYDRO INTELLIGENCE <span class="kicker-line"></span> 智水未来</div><h1 id="hero-title"><span class="hero-title-line">智联千川</span><span class="hero-title-line luminous-title">AI 护水利<span class="title-period">.</span></span></h1><p class="hero-description">感知江河脉动，洞见水利未来。<br>让每一份数据，汇成守护千川的力量。</p><div class="cinematic-actions"><a class="btn primary hero-primary" href="#/monitor"><span>开启全域监测</span>${icon('arrow')}</a><a class="hero-secondary" href="#/ai"><span class="play-orbit">${icon('play')}</span><span>探索 AI 视觉</span></a></div><div class="hero-proof"><span>01 / 流域感知</span><span>02 / 实时洞察</span><span>03 / 智能交互</span></div></div><div class="scene-telemetry"><span class="telemetry-label"><i class="status-dot"></i> SENSOR NETWORK / DEMO</span><div class="telemetry-value">08<span>个模拟监测节点</span></div><div class="telemetry-bars" aria-hidden="true">${Array.from({length:24},(_,i)=>`<i style="height:${12+(i*17%28)}px;animation-delay:${i*80}ms"></i>`).join('')}</div><span class="telemetry-note">感知 · 联接 · 洞察</span></div><div class="hero-bottom"><a class="scroll-cue" href="#overview"><span class="scroll-line"></span><span>向下探索 <small>SCROLL TO EXPLORE</small></span></a><div class="hero-bottom-right"><span class="simulation-label">CONCEPT VISUALIZATION · 前端模拟</span><button class="motion-control" id="toggle-motion" aria-pressed="${state.motionPaused}" aria-label="${state.motionPaused?'继续场景动画':'暂停场景动画'}">${icon(state.motionPaused?'play':'pause')}<span>${state.motionPaused?'继续动态':'暂停动态'}</span></button></div></div></section><section class="overview-deck" id="overview"><div class="deck-heading"><div><span class="section-kicker">01 / RIVER INTELLIGENCE</span><h2>万川相联，尽在掌握<span>.</span></h2></div><p>从一个监测点，到一张流域感知网络。<br>每一次变化，都在这里清晰呈现。</p></div><div class="section-label"><h3>流域运行概况</h3><span class="live-caption"><i class="status-dot"></i>模拟数据 · 每 3 秒更新</span></div>${statCards()}<div class="content-grid">${mapPanel()}${chartPanel()}</div><div class="bottom-grid">${stationTable()}${alertsPanel()}</div><div class="exploration-links"><a href="#/monitor"><span class="exploration-index">01 / MONITOR</span><div>${icon('wave')}<h3>从感知，到洞察</h3><span>↗</span></div><p>在实时曲线与流域地图中，读懂江河的信号。</p></a><a href="#/ai"><span class="exploration-index">02 / VISION LAB</span><div>${icon('scan')}<h3>向水下，再看深一点</h3><span>↗</span></div><p>用一次视觉交互，探索水下目标检测的表达。</p></a><a href="#/knowledge"><span class="exploration-index">03 / WATER NOTES</span><div>${icon('book')}<h3>与水共生，向未来</h3><span>↗</span></div><p>从一滴水开始，认识水资源与数字水利。</p></a></div></section>`}
function renderMonitor(){return `${header('监测总览','一张图读懂流域，让变化可见，让响应及时。',`<div class="monitor-toolbar"><button class="btn realtime-toggle" id="toggle-live">${icon(state.paused?'play':'pause')}<span>${state.paused?'继续刷新':'暂停刷新'}</span></button><button class="btn primary" id="export-csv">${icon('download')}导出数据</button></div>`)}<div class="intro-note">${icon('info')}交互演示：点选地图站点查看趋势；点击“模拟水位上涨”触发阈值预警。数据由浏览器生成，地图为示意图。</div>${statCards()}<div class="content-grid monitor-layout">${mapPanel()}${chartPanel()}</div><div class="bottom-grid">${stationTable(true)}${alertsPanel()}</div>`}

const sampleSVG=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 600"><defs><linearGradient id="w" x2=".5" y2="1"><stop stop-color="#277789"/><stop offset="1" stop-color="#092b3b"/></linearGradient><radialGradient id="light"><stop stop-color="#91e3d2" stop-opacity=".15"/><stop offset="1" stop-color="#91e3d2" stop-opacity="0"/></radialGradient><linearGradient id="fish"><stop stop-color="#b3d2c0"/><stop offset="1" stop-color="#567e78"/></linearGradient></defs><path fill="url(#w)" d="M0 0h900v600H0z"/><ellipse cx="250" cy="90" rx="500" ry="300" fill="url(#light)"/><g fill="#b2eee1" opacity=".06"><path d="m100 0 90 0 400 600H420Z"/><path d="m280 0 45 0 210 600H380Z"/></g><g fill="none" stroke="#a1d0ca" stroke-width="1" opacity=".25"><circle cx="145" cy="340" r="6"/><circle cx="156" cy="285" r="3"/><circle cx="700" cy="180" r="5"/><circle cx="710" cy="145" r="3"/><circle cx="430" cy="470" r="5"/></g><g fill="url(#fish)" stroke="#b8cfc0" stroke-width="1"><path d="M225 220q70-70 160 0-90 65-160 0l-52-36 4 76Z"/><path d="m285 192 16-28 23 33M285 245l24 21 18-24"/><path d="M525 345q65-53 140 0-72 56-140 0l-37-31 1 65Z"/><path d="m577 322 13-23 21 26"/><path d="M610 160q34-27 70 0-38 26-70 0l-18-14v30Z"/></g><g fill="#1b343c"><circle cx="359" cy="215" r="5"/><circle cx="643" cy="341" r="4"/><circle cx="668" cy="158" r="2"/></g><g stroke="#cee2d4" opacity=".35" fill="none"><path d="M339 204q-10 18 0 32M627 332q-8 14 0 24M230 220h97M536 345h71"/></g><path d="M0 550q110-44 211-13t240 10 270 0 179 3v50H0Z" fill="#173e43"/><g stroke="#2e655d" fill="none" stroke-width="7" stroke-linecap="round"><path d="M95 580q-22-65 11-136M119 580q33-65 3-104M782 580q-30-100 6-178M810 580q40-68 5-123M841 580q-20-52 3-82"/></g><g opacity=".65" transform="translate(340 440) rotate(22)"><path d="M0 0h24v10l9 12v60H-9V22L0 10Z" fill="#93b8ae" stroke="#c3d6c4"/><path d="M-8 45h40v24H-8Z" fill="#648d88"/><path d="M2-5h20v8H2Z" fill="#4e7774"/></g><g font-family="sans-serif" fill="#b0d6d2" opacity=".5" font-size="11" letter-spacing="3"><text x="30" y="35">UNDERWATER / ILLUSTRATED DEMO</text><text x="30" y="575">智水监测 · 水下场景示意图</text></g></svg>`;
const sampleData='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(sampleSVG);
function renderAI(){return `${header('AI 水下目标识别','以视觉探索水下世界，体验智能感知的交互过程。',`<span class="badge blue">${icon('cpu')}前端模拟演示</span>`)}<div class="intro-note">${icon('info')}本页不运行 AI 模型。检测框与置信度为预设演示，上传任意图片均不会产生真实识别结果；图片仅在当前浏览器中处理。</div><div class="ai-layout"><section class="panel"><div class="panel-heading"><div class="panel-title"><h2>水下视觉工作台</h2><span class="badge">VISION LAB</span></div><span class="live-caption">支持 JPG / PNG / WebP</span></div><div class="detection-stage ${state.image?'':'empty'}" id="detection-stage">${stageHTML()}</div><div class="ai-actions"><div><input class="file-input" id="image-upload" type="file" accept="image/jpeg,image/png,image/webp"><label for="image-upload" class="btn upload-label">${icon('upload')}上传图片</label><button class="btn" id="load-sample">使用水下示例</button></div><button class="btn primary" id="detect-button" ${!state.image||state.detecting?'disabled':''}>${icon('scan')}${state.detecting?'模拟分析中…':'开始模拟识别'}</button></div><p class="ai-caption" id="image-note">${state.image?(state.sample?'当前：内置水下示意图 · 原创矢量插画':'当前：本地上传图片 · 仅做预设标注演示'):'选择一张图片或载入示例，即可开始体验。最大 10 MB。'}</p></section><section class="panel"><div class="panel-heading"><div class="panel-title"><h2>检测结果</h2><span class="badge green" id="result-count">${state.results.length} 个演示目标</span></div></div><div id="detection-results" role="status" aria-live="polite">${resultsHTML()}</div><div class="ai-guide"><h3>三步探索水下感知</h3><div class="guide-step"><span>1</span><p>上传水下照片，或选择内置示意图。</p></div><div class="guide-step"><span>2</span><p>点击模拟识别，查看扫描与标注过程。</p></div><div class="guide-step"><span>3</span><p>对照目标框与结果，了解视觉检测的表达方式。</p></div></div></section></div><div class="ai-bottom">${feature('scan','目标可视化','用边界框展示鱼类与水下异物等场景，让视觉检测的结果更直观。')}${feature('shield','本地图片预览','图片保留在当前浏览器内，不上传服务器，刷新页面后释放。')}${feature('cpu','面向真实应用的设想','未来可连接真实检测模型与传感设备；当前作品聚焦前端交互设计。')}</div>`}
function stageHTML(){if(!state.image)return `<div class="upload-placeholder">${icon('image')}<h3>让水下世界，被看见</h3><p>上传一张图片开始探索<br>或点击下方“使用水下示例”</p></div>`;return `<img src="${state.image}" alt="${state.sample?'内置水下鱼类与瓶子示意图':'用户上传的待演示图片'}" id="preview-image"><div class="stage-top"><span>VISION LAB / DEMO</span><span>${state.sample?'ILLUSTRATED SAMPLE':'LOCAL IMAGE'}</span></div><div class="detection-overlay" id="detection-overlay">${boxesHTML()}</div>${state.detecting?'<div class="scan-line"></div>':''}`}
function boxesHTML(){return state.results.map(r=>`<div class="detect-box" style="left:${r.box[0]}%;top:${r.box[1]}%;width:${r.box[2]}%;height:${r.box[3]}%"><span>${r.name} ${r.confidence}% · 模拟</span></div>`).join('')}
function resultsHTML(){return state.results.length?state.results.map((r,i)=>`<div class="result-item"><span class="result-number">0${i+1}</span><div><h3>${r.name}</h3><p>预设目标 · ${r.type} · 演示置信度</p></div><b>${r.confidence}%</b></div>`).join(''):`<div class="result-empty">${icon(state.detecting?'scan':'layers')}<p>${state.detecting?'正在生成模拟标注…':'等待开始模拟识别'}</p></div>`}
function feature(type,title,copy){return `<article class="feature-card">${icon(type)}<h3>${title}</h3><p>${copy}</p></article>`}

const articles=[
{id:'flood',category:'水灾害',title:'读懂水位，读懂江河的信号',desc:'水位在变化，它与流量有什么关系？从两个基本概念开始，认识流域监测。',icon:'wave',time:'3 分钟',body:['水位是水面相对某个基准面的高程；流量是单位时间通过某个过水断面的水体体积。它们描述的是不同的物理量。','在一定条件下，水位与流量存在对应关系，但河床变化、回水等因素都会影响这种关系。因此，判断汛情需要结合降雨、水位、流量与工程运行信息。','本平台的水位曲线与阈值均为交互演示预设，不能据此判断真实河流的防汛形势。'],tip:'试一试：前往监测总览，切换“水位”和“流量”，观察两种指标的单位与曲线。'},
{id:'reservoir',category:'水灾害',title:'水库，如何为洪水留出空间？',desc:'认识水库调蓄的基本思路，理解为什么防洪与蓄水需要统筹考虑。',icon:'layers',time:'3 分钟',body:['水库可以在一定范围内调节来水与下泄水量。防洪调度的一个重要思路，是利用预留空间拦蓄一部分洪水，减轻下游的防洪压力。','蓄水需要统筹防洪、供水、生态等目标，实际调度取决于工程条件、预报结果和批准的调度方案。','因此，“水库越满越好”并不适用于所有时段。认识水库，需要同时看水位、库容、入库与出库流量。'],tip:'思考：当上游来水增大时，只看一个水位数字，足够理解水库运行状态吗？'},
{id:'quality',category:'水生态',title:'水清不清，不能只靠眼睛判断',desc:'pH 是水质信息的一部分。了解多指标观测，为水环境建立更完整的画像。',icon:'quality',time:'2 分钟',body:['透明度与颜色可以反映某些水体特征，但清澈并不等于安全。水质评价需要依据用途与标准，结合多个检测指标进行。','pH 描述水的酸碱性；溶解氧反映溶于水中的氧含量。温度、污染物、营养盐等信息同样有助于理解水体状态。','本作品仅模拟展示 pH，不以单一 pH 数值推断水质类别、饮用安全或生态健康。'],tip:'在本平台中，“正常”只描述水位是否超过演示阈值，不代表真实水质评价。'},
{id:'saving',category:'水资源',title:'节约用水，从看见用水开始',desc:'从日常的小习惯入手，理解水资源为什么需要每一个人的参与。',icon:'drop',time:'2 分钟',body:['水资源在时间和空间上的分布并不均匀。节约用水不仅是减少账单，也是在减少取水、供水与污水处理过程中的资源消耗。','及时修复漏水、按需取水、采用适宜的节水器具，都是可以从日常开始的行动。','重复利用水要注意用途与卫生条件。作品倡导按需用水，不提供饮用水处理方案。'],tip:'给自己一个小任务：记录一天中三次用水的场景，找出一个可以减少浪费的环节。'},
{id:'digital',category:'数字水利',title:'数字孪生，让流域多一面镜子',desc:'从传感器到可视化，看看数字技术如何帮助人们理解复杂的水利系统。',icon:'cpu',time:'4 分钟',body:['数字孪生水利通过数字化表达、模拟分析与信息交互，辅助认识和管理现实中的水利对象。','传感观测提供数据基础，模型与分析帮助理解变化，可视化界面则把复杂信息呈现给使用者。实际系统需要长期的数据治理与专业验证。','本作品展示了其中“数据呈现与交互”的一环：模拟传感数据、联动站点与曲线、呈现预警。它没有接入真实数字孪生平台。'],tip:'一张清晰的地图和一条可交互的曲线，是把复杂信息讲清楚的起点。'},
{id:'underwater',category:'数字水利',title:'给水下世界，一双数字眼睛',desc:'认识目标检测的可视化语言，看看边界框和置信度分别表达什么。',icon:'scan',time:'3 分钟',body:['目标检测通常会给出物体类别、位置与模型置信度。边界框用于表达检测到的目标范围。','置信度是模型对结果的评分，不等同于经过验证的真实正确率。浑浊、遮挡、光照不足等情况，都会给水下视觉带来挑战。','本作品的识别流程仅用预设框与固定分数演示界面效果；上传图片不会触发真实视觉分析。'],tip:'前往 AI 水下识别页，使用内置示意图体验“图片—扫描—框选—结果”的交互。'}
];
function knowledgeArt(a,i){const colors=[['#e4f2ff','#83b9e9','#3e90d7'],['#e6f1f7','#8fb9cc','#5c96b4'],['#e5f4ef','#9bcbb8','#64a78d'],['#e9f4ff','#97c7ef','#5d9cda'],['#eaeffd','#a9b9e0','#798dc9'],['#e2f2f5','#8ebec9','#4c95aa']][i];return `<div class="knowledge-art" style="background:${colors[0]}"><span class="art-index">WATER NOTES / 0${i+1}</span><svg viewBox="0 0 340 160" fill="none" aria-hidden="true"><g opacity=".45" stroke="${colors[1]}" stroke-width=".6">${[0,1,2,3,4].map(n=>`<ellipse cx="260" cy="75" rx="${45+n*23}" ry="${25+n*13}"/>`).join('')}</g><path d="M0 135q50-30 100 0t100 0 140 0v30H0" fill="${colors[1]}" opacity=".23"/><path d="M0 150q70-27 140-2t200-9v30H0" fill="${colors[1]}" opacity=".35"/><g transform="translate(154 66) scale(2.5)" stroke="${colors[2]}" stroke-width=".9" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[a.icon]}"/></g><circle cx="115" cy="76" r="3" fill="${colors[1]}"/><circle cx="246" cy="118" r="2" fill="${colors[2]}" opacity=".5"/></svg></div>`}
function renderKnowledge(){return `${header('水利知识库','从一滴水开始，理解江河与我们的未来。',`<span class="badge blue">WATER NOTES · 水利手记</span>`)}<div class="knowledge-filters"><div class="filter-tabs" id="knowledge-tabs">${['全部内容','水灾害','水资源','水生态','数字水利'].map(c=>`<button data-category="${c}" class="${c===state.category?'active':''}" aria-pressed="${c===state.category}">${c}</button>`).join('')}</div><label class="search-box">${icon('search')}<input type="search" id="knowledge-search" placeholder="搜索水利知识…" aria-label="搜索水利知识" value="${escapeHTML(state.search)}"></label></div><div class="knowledge-grid" id="knowledge-grid">${knowledgeCards()}</div><div class="intro-note" style="margin-top:24px">${icon('book')}水利手记为作品编写的基础概念介绍。延伸阅读可访问 <a href="https://www.mwr.gov.cn/" target="_blank" rel="noopener" class="source-link">水利部官方网站 ↗</a></div>`}
function knowledgeCards(){const filtered=articles.filter(a=>(state.category==='全部内容'||a.category===state.category)&&(a.title+a.desc+a.body.join('')).includes(state.search.trim()));return filtered.length?filtered.map(a=>`<article class="knowledge-card">${knowledgeArt(a,articles.indexOf(a))}<div class="knowledge-card-content"><span class="badge ${a.category==='水生态'?'green':'blue'}">${a.category}</span><h2>${a.title}</h2><p>${a.desc}</p><div class="knowledge-card-bottom"><span>${a.time}阅读 · 原创科普</span><button data-article="${a.id}">阅读手记 ↗</button></div></div></article>`).join(''):'<div class="no-results">没有找到相关手记，试试“水位”“水库”或“数字”。</div>'}
function renderAbout(){return `${header('方案与团队','以水利为题，以交互为语言，探索专业与设计的连接。')}<section class="about-hero"><div class="eyebrow">OUR VISION / 智水未来</div><h1>让江河有感知<br>让守护更智慧。</h1><p>“智水监测”是一件面向水利场景的网页设计作品。我们把抽象的数据转化为可观察的曲线、可探索的地图与可体验的交互，让数字水利更容易被理解。</p></section><section class="about-section"><h2>一条从感知到理解的路径</h2><div class="pipeline">${[['01 / SENSE','多源感知','以水位、流量、pH 等模拟指标，构建浏览器中的数据流。'],['02 / CONNECT','流域联动','地图点位、监测卡片与趋势曲线共享同一个站点状态。'],['03 / UNDERSTAND','可视洞察','通过阈值变色、事件弹窗和模拟检测框呈现复杂信息。'],['04 / ACT','交互响应','在切换、筛选、暂停与导出中，完成一次主动探索。']].map(r=>`<article class="feature-card"><span class="number">${r[0]}</span><h3>${r[1]}</h3><p>${r[2]}</p></article>`).join('')}</div></section><section class="about-section"><h2>作品边界与实现</h2><div class="scope-grid"><div class="panel scope-panel"><h3>当前已实现</h3>${[['实时监测','浏览器生成 · 3 秒刷新'],['联动可视化','8 站点 · 3 类指标 · 3 个时间范围'],['预警交互','模拟水位上涨 · 阈值变色 · 弹窗'],['视觉演示','本地图片预览 · 预设检测框'],['数据导出','当前区域的模拟观测 CSV']].map(r=>`<div class="scope-row"><span>${r[0]}</span><b>${r[1]}</b></div>`).join('')}</div><div class="panel scope-panel"><h3>面向未来的连接</h3><p>真实应用可以接入水文传感器、专业地图服务与经过验证的视觉模型。当前作品为纯前端展示，不采集真实站点数据，不运行深度学习模型，也不用于防汛调度或水质评价。</p><p style="margin-top:16px">技术：HTML / CSS / JavaScript / 本地 Chart.js。页面与资源独立存储，可离线启动，无需后端与密钥。</p><a class="btn text" href="#/monitor" style="margin-top:15px">探索监测工作台 ${icon('arrow')}</a></div></div></section><section class="about-section"><div class="section-label"><h2>共同构建智水未来</h2><span class="badge">团队配置示例 · 姓名待填写</span></div><div class="team-grid">${[['设','体验与视觉设计','负责信息架构、界面设计与交互表达。'],['码','前端开发与实现','负责模拟数据、图表联动与响应式实现。'],['水','水利场景与内容','负责场景构思、基础科普与演示叙事。']].map(t=>`<article class="feature-card"><div class="team-avatar">${t[0]}</div><h3>${t[1]}</h3><small>成员姓名待填写</small><p>${t[2]}</p></article>`).join('')}</div></section>`}

let sceneController=null,homeEntrancePlayed=false,navigationByKeyboard=false;
function render(){sceneController?.destroy();sceneController=null;document.body.dataset.page=state.page;state.chart?.destroy();state.chart=null;$('#main').innerHTML=`<div class="page-enter">${({home:renderHome,monitor:renderMonitor,ai:renderAI,knowledge:renderKnowledge,about:renderAbout}[state.page])()}</div>`;$('#breadcrumb-title').textContent=navs.find(n=>n[0]===state.page)[2];$$('.nav-link').forEach(a=>{const active=a.dataset.page===state.page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=`${navs.find(n=>n[0]===state.page)[2]} · 智水监测`;bindPage();if($('#trend-chart'))makeChart();mountCinematicMotion();applyPaused()}
function mountCinematicMotion(){
  const canvas=$('#digital-river');
  if(!canvas)return;
  if(window.HydroScene)sceneController=new window.HydroScene(canvas,{paused:state.motionPaused||state.paused,getReadings:()=>[stations[0].level,stations[3].level,stations[7].level]});
  $('#toggle-motion').onclick=()=>{state.motionPaused=!state.motionPaused;const b=$('#toggle-motion');b.innerHTML=`${icon(state.motionPaused?'play':'pause')}<span>${state.motionPaused?'继续动态':'暂停动态'}</span>`;b.setAttribute('aria-pressed',state.motionPaused);b.setAttribute('aria-label',state.motionPaused?'继续场景动画':'暂停场景动画');applyPaused()};
  if(!homeEntrancePlayed&&!navigationByKeyboard&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
    $$('.hero-kicker,.hero-title-line,.hero-description,.cinematic-actions,.hero-proof').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(18px)'},{opacity:1,transform:'translateY(0)'}],{duration:600,delay:i*80,easing:'cubic-bezier(0.23, 1, 0.32, 1)',fill:'backwards'}));
  }
  homeEntrancePlayed=true;
}
function route(){const route=location.hash.replace('#/','')||'home';state.page=navs.some(n=>n[0]===route)?route:'home';closeSidebar();render();window.scrollTo(0,0)}
function makeChart(){if(typeof Chart==='undefined'){const el=$('.chart-area');el.innerHTML='<p class="article-tip">图表组件未能加载，请检查本地资源。监测数字与表格仍可查看。</p>';return}const m=metricMeta[state.metric],s=stations[state.selected],canvas=$('#trend-chart'),ctx=canvas.getContext('2d');const gradient=ctx.createLinearGradient(0,0,0,280);gradient.addColorStop(0,m.color+'30');gradient.addColorStop(1,m.color+'00');const chartData=getChartData();state.chart=new Chart(ctx,{type:'line',data:{labels:chartData.labels,datasets:[{label:m.name,data:chartData.values,borderColor:m.color,borderWidth:2,backgroundColor:gradient,fill:true,tension:.38,pointRadius:0,pointHoverRadius:4,pointHitRadius:12},...(state.metric==='level'?[{label:'演示阈值',data:chartData.values.map(()=>s.limit),borderColor:'#f68b8b',borderWidth:1,borderDash:[4,5],pointRadius:0,fill:false}]:[])]},options:{responsive:true,maintainAspectRatio:false,animation:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:false},tooltip:{backgroundColor:'#11283d',padding:12,titleFont:{family:'DM',size:10},bodyFont:{family:'DM',size:10},displayColors:true,callbacks:{label:c=>`${c.dataset.label}: ${fmt(c.parsed.y,state.metric==='flow'?0:2)} ${m.unit}`}}},scales:{x:{grid:{display:false},border:{display:false},ticks:{maxTicksLimit:5,maxRotation:0,color:'#7898b0',font:{family:'DM',size:10},padding:7}},y:{border:{display:false},grid:{color:'#163047',drawTicks:false},ticks:{maxTicksLimit:5,color:'#7898b0',font:{family:'DM',size:10},padding:9},...(state.metric==='ph'?{min:6.5,max:8}:{})}}}})}
function getChartData(){const now=Date.now(),hours=parseInt(state.range),history=histories[state.selected];return {labels:history.map((_,i)=>new Date(now-(24-i)*hours*3600000/24).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})),values:history.map(h=>h[state.metric])}}
function updateReadings(){if(!['home','monitor'].includes(state.page))return;const s=stations[state.selected],list=visibleStations(),warnings=list.filter(isWarn).length;const values={drop:fmt(s.level),flow:fmt(s.flow,0),quality:fmt(s.ph,1),pin:String(list.length).padStart(2,'0')};Object.entries(values).forEach(([k,v])=>{const el=$(`[data-stat="${k}"]`);if(el)el.textContent=v});$('[data-bottom="drop"]').innerHTML=`${s.name} · <span class="${isWarn(s)?'negative':'positive'}">${isWarn(s)?'超过阈值':'阈值内'}</span>`;$('[data-bottom="pin"]').innerHTML=`<span class="${warnings?'negative':'positive'}">${warnings?'● '+warnings+' 个水位预警':'● 全部水位正常'}</span>`;$('#map-detail').innerHTML=mapDetail();$$('.station-pin').forEach(pin=>{const n=+pin.dataset.station,st=stations[n];pin.classList.toggle('warn',isWarn(st));pin.classList.toggle('selected',n===state.selected);pin.setAttribute('aria-pressed',n===state.selected);pin.setAttribute('aria-label',`${st.name}，水位 ${fmt(st.level)} 米，${isWarn(st)?'预警':'正常'}`);$('.pin-hover',pin).textContent=`${fmt(st.level)} m · ${fmt(st.flow,0)} m³/s · pH ${fmt(st.ph,1)}`});updateTableReadings();$('#chart-summary').innerHTML=chartSummary();$('#chart-station').textContent=`${s.name} · 模拟历史与实时数据`;if(state.chart){const data=getChartData();state.chart.data.labels=data.labels;state.chart.data.datasets[0].data=data.values;if(state.chart.data.datasets[1])state.chart.data.datasets[1].data=data.values.map(()=>s.limit);state.chart.update('none')}}
function updateTableReadings(){const rows=$$('#station-table-body tr'),list=state.page==='monitor'?visibleStations():visibleStations().slice(0,4);rows.forEach((row,i)=>{const s=list[i];if(!s)return;const cells=row.cells;cells[1].textContent=fmt(s.level)+' m';cells[2].textContent=state.page==='monitor'?fmt(s.flow,0)+' / '+fmt(s.ph,1):fmt(s.limit)+' m';const badge=$('.badge',cells[3]);badge.textContent=isWarn(s)?'水位预警':'正常';badge.className='badge '+(isWarn(s)?'red':'green')})}
function tick(){if(state.paused||document.hidden)return;state.tick++;stations.forEach((s,i)=>{s.level=+(s.base+Math.sin(state.tick*.24+i)*.045).toFixed(2);s.flow=Math.round([1260,1845,526,2360,2150,1980,318,875][i]+Math.sin(state.tick*.3+i)*48);s.ph=+([7.2,7.4,7.1,7.3,7.2,7.5,7.3,7.1][i]+Math.sin(state.tick*.16+i)*.04).toFixed(2);histories[i].push({level:s.level,flow:s.flow,ph:s.ph});histories[i].shift()});updateReadings()}
function selectStation(i,scroll=false){state.selected=i;updateReadings();if(state.chart){state.chart.destroy();makeChart()}if(scroll)$('#river-map').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'})}
function bindPage(){$('.scroll-cue')?.addEventListener('click',e=>{e.preventDefault();$('#overview').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})});const main=$('#main');main.onclick=e=>{const st=e.target.closest('[data-station]'),view=e.target.closest('[data-view-station]'),metric=e.target.closest('[data-metric]'),range=e.target.closest('[data-range]'),article=e.target.closest('[data-article]'),category=e.target.closest('[data-category]'),alert=e.target.closest('[data-alert]');if(st)selectStation(+st.dataset.station);if(view)selectStation(+view.dataset.viewStation,true);if(metric){state.metric=metric.dataset.metric;refreshChartControls()}if(range){state.range=range.dataset.range;refreshChartControls()}if(article)openArticle(article.dataset.article);if(category){state.category=category.dataset.category;$$('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===state.category);b.setAttribute('aria-pressed',b.dataset.category===state.category)});$('#knowledge-grid').innerHTML=knowledgeCards()}if(alert)openStationAlert(+alert.dataset.alert)};$('#region-select')?.addEventListener('change',e=>{state.region=e.target.value;if(!visibleStations().includes(stations[state.selected]))state.selected=stationIndex(visibleStations()[0]);render()});$('#map-expand')?.addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if($('#river-map').requestFullscreen)await $('#river-map').requestFullscreen();else toast('当前浏览器不支持全屏，可使用页面缩放查看。')}catch{toast('当前浏览器未允许全屏，可直接在地图上查看站点。')}});$('#toggle-live')?.addEventListener('click',()=>{state.paused=!state.paused;const b=$('#toggle-live');b.innerHTML=`${icon(state.paused?'play':'pause')}<span>${state.paused?'继续刷新':'暂停刷新'}</span>`;applyPaused();toast(state.paused?'模拟数据刷新已暂停':'模拟数据刷新已继续')});$('#export-csv')?.addEventListener('click',exportCSV);$('#simulate-storm')?.addEventListener('click',simulateStorm);$('#all-alerts')?.addEventListener('click',openAlertLog);$('#load-sample')?.addEventListener('click',loadSample);$('#image-upload')?.addEventListener('change',uploadImage);$('#detect-button')?.addEventListener('click',detect);$('#knowledge-search')?.addEventListener('input',e=>{state.search=e.target.value;$('#knowledge-grid').innerHTML=knowledgeCards()});bindDrop();fitDetectionOverlay()}
function refreshChartControls(){$$('[data-metric]').forEach(b=>{const active=b.dataset.metric===state.metric;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});$$('[data-range]').forEach(b=>{const active=b.dataset.range===state.range;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});$('#chart-summary').innerHTML=chartSummary();$('#chart-legend').textContent=`${metricMeta[state.metric].name} (${metricMeta[state.metric].unit})`;state.chart?.destroy();makeChart()}
function applyPaused(){document.body.classList.toggle('paused',state.paused);document.body.classList.toggle('motion-paused',state.motionPaused);sceneController?.setPaused(state.motionPaused||state.paused);$$('.refresh-label').forEach(el=>el.textContent=state.paused?'已暂停':'动态采集');$$('.realtime-toggle').forEach(el=>el.classList.toggle('live-paused',state.paused))}
function simulateStorm(){if(state.storm){stations.forEach(s=>{s.base=s.originalBase??s.base;delete s.originalBase;s.level=s.base});state.storm=false;state.alerts.unshift({station:state.selected,time:new Date(),title:'水位上涨演示已恢复常态',kind:'info'});render();toast('已恢复初始模拟水位，原有江宁闸演示预警保留。');return}const s=stations[state.selected];s.originalBase=s.base;s.base=+(s.limit+.62).toFixed(2);s.level=s.base;histories[state.selected][24].level=s.level;state.storm=true;state.alerts.unshift({station:state.selected,time:new Date(),title:`${s.name}水位超过演示阈值`,kind:'warn'});render();openStationAlert(state.selected)}
function openStationAlert(i){const s=stations[i];openDialog(`<div class="dialog-eyebrow">SIMULATED ALERT / 模拟监测事件</div><span class="badge ${isWarn(s)?'red':'green'}">${isWarn(s)?'水位阈值预警':'当前水位正常'}</span><h2>${s.name}</h2><p>站点编号 ${s.id} · 阈值 ${fmt(s.limit)} m</p><div class="dialog-metric" style="color:${isWarn(s)?'#e36c6c':'#2687da'}">${fmt(s.level)}<span>m / 当前模拟水位</span></div><p>${isWarn(s)?`当前水位超过前端演示阈值 ${fmt(s.level-s.limit)} m。地图点位已同步变红，可查看趋势变化。`:'当前水位低于演示阈值，可继续查看监测趋势。'}此事件仅用于网页交互展示。</p><div class="dialog-actions"><button class="btn" data-close-dialog>关闭</button><button class="btn primary" id="focus-alert-station">查看监测站点 ${icon('arrow')}</button></div>`);$('#focus-alert-station').onclick=()=>{$('#dialog').close();state.selected=i;state.region='all';if(state.page==='monitor'){render();$('#river-map').scrollIntoView({block:'center'})}else location.hash='/monitor'}}
function openAlertLog(){openDialog(`<div class="dialog-eyebrow">EVENT LOG / 演示事件记录</div><h2>预警与动态</h2><p>记录保存在当前页面会话，刷新后重置。</p>${state.alerts.slice(0,10).map(a=>`<div class="scope-row"><span>${timeString(a.time)}</span><b>${a.title}</b></div>`).join('')}<div class="dialog-actions"><button class="btn primary" data-close-dialog>了解了</button></div>`)}
function exportCSV(){const rows=[['数据类型','导出时间','站点编号','站点名称','水位(m)','流量(m³/s)','pH','演示阈值(m)','状态'],...visibleStations().map(s=>['前端模拟',new Date().toISOString(),s.id,s.name,s.level,s.flow,s.ph,s.limit,isWarn(s)?'演示预警':'正常'])];download('\uFEFF'+rows.map(r=>r.join(',')).join('\r\n'),'智水监测-模拟数据.csv','text/csv;charset=utf-8');toast(`已导出 ${visibleStations().length} 个站点的模拟数据`)}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function resetDetection(){clearTimeout(state.detectionTimer);state.detectionTimer=null;state.detecting=false;state.results=[]}
function releaseImage(){if(state.image?.startsWith('blob:'))URL.revokeObjectURL(state.image)}
function loadSample(){state.uploadToken++;resetDetection();releaseImage();state.image=sampleData;state.sample=true;render();toast('已载入水下示意图，点击开始模拟识别')}
async function uploadImage(e){const file=e.target.files?.[0];if(file)await acceptImage(file)}
async function acceptImage(file){const token=++state.uploadToken;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('请选择 JPG、PNG 或 WebP 图片');return}if(file.size>10*1024*1024){toast('图片超过 10 MB，请选择较小的图片');return}const url=URL.createObjectURL(file),image=new Image();image.src=url;try{await image.decode();if(token!==state.uploadToken){URL.revokeObjectURL(url);return}resetDetection();releaseImage();state.image=url;state.sample=false;if(state.page==='ai')render();toast('图片已在本地载入，识别结果将为预设演示')}catch{URL.revokeObjectURL(url);if(token===state.uploadToken)toast('无法读取这张图片，请使用有效的图片文件')}}
function fitDetectionOverlay(){const img=$('#preview-image'),overlay=$('#detection-overlay'),stage=$('#detection-stage');if(!img||!overlay||!stage)return;const fit=()=>{if(!img.naturalWidth)return;const scale=Math.min(stage.clientWidth/img.naturalWidth,stage.clientHeight/img.naturalHeight),w=img.naturalWidth*scale,h=img.naturalHeight*scale;Object.assign(overlay.style,{width:w+'px',height:h+'px',left:(stage.clientWidth-w)/2+'px',top:(stage.clientHeight-h)/2+'px',right:'auto',bottom:'auto'})};if(img.complete)fit();else img.addEventListener('load',fit,{once:true})}
function bindDrop(){const el=$('#detection-stage');if(!el)return;el.ondragover=e=>{e.preventDefault();el.style.outline='2px solid #68a9ed'};el.ondragleave=()=>el.style.outline='';el.ondrop=e=>{e.preventDefault();el.style.outline='';if(e.dataTransfer.files[0])acceptImage(e.dataTransfer.files[0])}}
function detect(){if(!state.image||state.detecting)return;resetDetection();state.detecting=true;render();state.detectionTimer=setTimeout(()=>{state.detecting=false;state.results=state.sample?[{name:'鱼类目标',confidence:96.8,type:'示例标注',box:[19,27,25,19]},{name:'鱼类目标',confidence:94.2,type:'示例标注',box:[53,49,23,15]},{name:'水下异物',confidence:89.5,type:'示例标注',box:[33,69,12,24]}]:[{name:'演示目标 A',confidence:96.8,type:'预设框 · 非真实识别',box:[19,27,25,19]},{name:'演示目标 B',confidence:89.5,type:'预设框 · 非真实识别',box:[53,49,23,15]}];if(state.page==='ai')render();toast('模拟标注已生成，框选位置与分数均为预设演示')},1800)}
function openArticle(id){const a=articles.find(a=>a.id===id);if(!a)return;openDialog(`<div class="dialog-eyebrow">WATER NOTES / ${a.category}</div><h2>${a.title}</h2>${a.body.map(p=>`<p>${p}</p>`).join('')}<div class="article-tip">${a.tip}</div><div class="dialog-actions"><button class="btn" data-close-dialog>返回知识库</button><button class="btn primary" id="article-explore">${a.id==='underwater'?'体验 AI 演示':'探索监测总览'} ${icon('arrow')}</button></div>`);$('#article-explore').onclick=()=>{$('#dialog').close();location.hash=a.id==='underwater'?'/ai':'/monitor'}}
function openDialog(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal();$$('[data-close-dialog]').forEach(b=>b.onclick=()=>$('#dialog').close())}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600)}
function closeSidebar(){$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');syncSidebar()}
function syncSidebar(){const hidden=matchMedia('(max-width:760px)').matches&&!$('#sidebar').classList.contains('open');$('#main-nav').inert=hidden;$('#main-nav').setAttribute('aria-hidden',String(hidden))}
function updateClock(){$('#clock').textContent=new Date().toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})}
$('#main-nav').innerHTML=navs.map(([page,type,name])=>`<a class="nav-link" href="#/${page}" data-page="${page}">${icon(type)}<span>${name}</span></a>`).join('');$('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'})});$('#notification-button').innerHTML=icon('bell');$('#notification-button').onclick=openAlertLog;$('#dialog-close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close()}});$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-controls','sidebar');$('#menu-toggle').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',open);syncSidebar()};$('#sidebar-shade').onclick=closeSidebar;document.addEventListener('keydown',e=>{navigationByKeyboard=true;if(e.key==='Escape')closeSidebar()});document.addEventListener('pointerdown',()=>{navigationByKeyboard=false});window.addEventListener('resize',()=>{syncSidebar();fitDetectionOverlay()});window.addEventListener('hashchange',route);window.addEventListener('pagehide',()=>{sceneController?.destroy();sceneController=null;state.chart?.stop()});window.addEventListener('pageshow',e=>{if(e.persisted&&state.page==='home')mountCinematicMotion()});document.addEventListener('visibilitychange',()=>document.body.classList.toggle('page-hidden',document.hidden));updateClock();setInterval(updateClock,1000);setInterval(tick,3000);route();
